const { useState } = React;

const STYLE = `
  @scope {
    .cb-item {
      animation: cb-stagger-in 400ms var(--tau-ease-out) both;
      animation-delay: calc((sibling-index() - 1) * var(--cb-step));
    }
    .cb-bar {
      animation: cb-stagger-bar 400ms linear both;
      animation-delay: calc((sibling-index() - 1) * var(--cb-step));
      transform-origin: left center;
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
  @keyframes cb-stagger-in {
    from { opacity: 0; transform: translateY(12px) scale(0.9); }
    to { opacity: 1; transform: none; }
  }
  @keyframes cb-stagger-bar {
    from { transform: scaleX(0); }
    to { transform: scaleX(1); }
  }
`;

const Stepper = ({ value, min, max, onChange }) => (
  <div className="flex items-center gap-1.5">
    <ui.IconButton aria-label="减少" disabled={value <= min} onClick={() => onChange(value - 1)}>
      <icons.Minus className="size-4" />
    </ui.IconButton>
    <span className="w-16 text-center text-tau-body text-ink-1">{value} 个元素</span>
    <ui.IconButton aria-label="增加" disabled={value >= max} onClick={() => onChange(value + 1)}>
      <icons.Plus className="size-4" />
    </ui.IconButton>
  </div>
);

const Component = () => {
  const [count, setCount] = useState(6);
  const [step, setStep] = useState(80);
  const [round, setRound] = useState(0);
  const total = (count - 1) * step + 400;
  const indexes = Array.from({ length: count }, (_, index) => index + 1);

  // 每次改动都换 key 重新挂载，让动画从头播放
  const replay = () => setRound(value => value + 1);
  const change = setter => value => {
    setter(value);
    replay();
  };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="flex flex-col gap-4 rounded-tau-md border border-line-1 p-4" style={{ "--cb-step": `${step}ms` }}>
        <div key={`items-${round}`} className="flex flex-wrap gap-3">
          {indexes.map(index => (
            <div
              key={index}
              className="cb-item grid size-12 place-items-center rounded-tau-sm bg-accent font-tau-mono text-tau-body text-ink-inverse shadow-card"
            >
              {index}
            </div>
          ))}
        </div>
        <div key={`bars-${round}`} className="flex flex-col gap-1">
          {indexes.map(index => (
            <div key={index} className="flex items-center gap-2">
              <span className="w-28 shrink-0 font-tau-mono text-tau-tiny text-ink-3">
                {index} → {(index - 1) * step}ms
              </span>
              <div className="relative h-1.5 min-w-0 flex-1 rounded-full bg-track">
                <div
                  className="absolute inset-y-0 rounded-full bg-accent-soft"
                  style={{ left: `${(((index - 1) * step) / total) * 100}%`, width: `${(400 / total) * 100}%` }}
                />
              </div>
            </div>
          ))}
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <Stepper value={count} min={2} max={10} onChange={change(setCount)} />
        <label className="flex min-w-[220px] flex-1 items-center gap-3">
          <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">间隔</span>
          <input
            type="range"
            min={20}
            max={200}
            step={10}
            value={step}
            onChange={event => setStep(Number(event.target.value))}
            onPointerUp={replay}
            onKeyUp={replay}
            className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
          />
          <span className="w-14 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{step}ms</span>
        </label>
        <ui.Button variant="secondary" size="sm" icon={icons.RotateCcw} onClick={replay}>
          重新播放
        </ui.Button>
      </div>
      <code className="w-fit min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
        animation-delay: calc((sibling-index() - 1) * {step}ms);
      </code>
    </div>
  );
};

