const { useEffect, useRef, useState } = React;

const STYLE = `
  @scope {
    .cb-cell {
      width: calc(100% / sibling-count());
      transition: width 300ms var(--tau-ease-out);
    }
    .cb-cell-in { animation: cb-count-in 300ms var(--tau-ease-out) both; }
  }
  @keyframes cb-count-in {
    from { opacity: 0; transform: scale(0.8); }
    to { opacity: 1; transform: none; }
  }
`;
const COLORS = ["bg-tag-1", "bg-tag-2", "bg-tag-3", "bg-tag-4", "bg-tag-5"];
const MIN = 1;
const MAX = 8;

const formatPercent = value => `${Number(value.toFixed(2))}%`;

const Component = () => {
  const rowRef = useRef(null);
  const [count, setCount] = useState(4);
  const [measure, setMeasure] = useState(null);
  const indexes = Array.from({ length: count }, (_, index) => index + 1);

  // 读取浏览器真实算出的宽度，验证 sibling-count() 已生效
  useEffect(() => {
    const row = rowRef.current;
    if (!row) return;
    const read = () => {
      const cell = row.firstElementChild;
      if (!cell) return;
      setMeasure({ row: row.getBoundingClientRect().width, cell: cell.getBoundingClientRect().width });
    };
    const observer = new ResizeObserver(read);
    observer.observe(row);
    const timer = setTimeout(read, 320);
    return () => {
      observer.disconnect();
      clearTimeout(timer);
    };
  }, [count]);

  return (
    <div className="flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="flex flex-col gap-3 rounded-tau-md border border-line-1 p-4">
        <div ref={rowRef} className="flex h-16 w-full">
          {indexes.map(index => (
            <div key={index} className="cb-cell min-w-0 px-0.5">
              <div
                className={`cb-cell-in grid h-full place-items-center rounded-tau-sm font-tau-mono text-tau-body text-ink-inverse ${COLORS[(index - 1) % COLORS.length]}`}
              >
                {index}
              </div>
            </div>
          ))}
        </div>
        <div className="flex w-full">
          {indexes.map(index => (
            <div key={index} className="cb-cell min-w-0 border-x border-line-1 px-1 text-center">
              <span className="block truncate font-tau-mono text-tau-tiny text-ink-3">{formatPercent(100 / count)}</span>
            </div>
          ))}
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <ui.Button variant="secondary" size="sm" icon={icons.Minus} disabled={count <= MIN} onClick={() => setCount(value => value - 1)}>
          移除
        </ui.Button>
        <ui.Button variant="secondary" size="sm" icon={icons.Plus} disabled={count >= MAX} onClick={() => setCount(value => value + 1)}>
          添加
        </ui.Button>
        <span className="text-tau-body text-ink-2">共 {count} 个元素</span>
      </div>
      <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5">
        <dt className="font-tau-mono text-tau-sm text-ink-3">sibling-count()</dt>
        <dd className="m-0 font-tau-mono text-tau-sm text-ink-1">{count}</dd>
        <dt className="font-tau-mono text-tau-sm text-ink-3">width</dt>
        <dd className="m-0 min-w-0 break-all font-tau-mono text-tau-sm text-ink-1">
          calc(100% / {count}) = {formatPercent(100 / count)}
        </dd>
        <dt className="font-tau-mono text-tau-sm text-ink-3">实测宽度</dt>
        <dd className="m-0 font-tau-mono text-tau-sm text-ink-1">
          {measure ? `${measure.cell.toFixed(1)}px / ${measure.row.toFixed(1)}px` : "—"}
        </dd>
      </dl>
    </div>
  );
};

