.stacked-card {
  --offset: calc((sibling-index() - 1) * 8px);
  transform: translateY(var(--offset));
  z-index: calc(sibling-count() - sibling-index());
}

content.content:
const { useState } = React;

const STYLE = `
  @scope {
    .cb-card {
      --cb-offset: calc((sibling-index() - 1) * var(--cb-step));
      transform: translateY(var(--cb-offset));
      transition: transform 300ms var(--tau-ease-out);
    }
    .cb-stack[data-z="on"] .cb-card {
      z-index: calc(sibling-count() - sibling-index());
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;
const NAMES = ["A", "B", "C", "D", "E", "F", "G", "H"];
const MARKS = ["bg-tag-1", "bg-tag-2", "bg-tag-3", "bg-tag-4", "bg-tag-5", "bg-tag-1", "bg-tag-2", "bg-tag-3"];
const CARD_HEIGHT = 112;

const Component = () => {
  const [order, setOrder] = useState([0, 1, 2, 3, 4]);
  const [step, setStep] = useState(12);
  const [reverseZ, setReverseZ] = useState(true);
  const count = order.length;

  const add = () => setOrder(list => [...list, NAMES.findIndex((_, id) => !list.includes(id))]);
  const remove = () => setOrder(list => list.slice(0, -1));
  // 顶部卡片移到末尾：DOM 顺序变了，sibling-index() 自动重算
  const rotate = () => setOrder(list => [...list.slice(1), list[0]]);

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="flex items-start justify-center rounded-tau-md border border-line-1 p-4">
          <div
            className="cb-stack relative w-full max-w-[280px]"
            data-z={reverseZ ? "on" : "off"}
            style={{ "--cb-step": `${step}px`, height: CARD_HEIGHT + (count - 1) * step }}
          >
            {order.map(id => (
              <div
                key={id}
                className="cb-card absolute inset-x-0 top-0 flex flex-col justify-between rounded-tau-md border border-line-1 bg-surface p-3 shadow-card"
                style={{ height: CARD_HEIGHT }}
              >
                <div className="flex items-center gap-2">
                  <span className={`size-2.5 rounded-full ${MARKS[id]}`} />
                  <span className="text-tau-body text-ink-1">卡片 {NAMES[id]}</span>
                </div>
                <div className="flex flex-col gap-1.5">
                  <div className="h-1.5 w-3/4 rounded-full bg-hover" />
                  <div className="h-1.5 w-1/2 rounded-full bg-hover" />
                </div>
              </div>
            ))}
          </div>
        </div>
        <div className="flex min-w-0 flex-col gap-1 rounded-tau-md bg-hover px-3 py-2.5">
          <div className="grid grid-cols-[minmax(0,1fr)_auto_auto_auto] gap-x-3 font-tau-mono text-tau-tiny text-ink-3">
            <span>卡片</span>
            <span className="text-right">index</span>
            <span className="text-right">offset</span>
            <span className="text-right">z-index</span>
          </div>
          {order.map((id, position) => (
            <div key={id} className="grid grid-cols-[minmax(0,1fr)_auto_auto_auto] gap-x-3 font-tau-mono text-tau-sm text-ink-1">
              <span className="flex items-center gap-1.5">
                <span className={`size-2 rounded-full ${MARKS[id]}`} />
                {NAMES[id]}
              </span>
              <span className="text-right">{position + 1}</span>
              <span className="text-right">{position * step}px</span>
              <span className="text-right">{reverseZ ? count - position - 1 : "auto"}</span>
            </div>
          ))}
          <span className="mt-1 text-tau-sm text-ink-3">
            {reverseZ ? `卡片 ${NAMES[order[0]]} 在最上层` : `未设 z-index，后面的卡片 ${NAMES[order[count - 1]]} 盖住前面`}
          </span>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <div className="flex items-center gap-1.5">
          <ui.IconButton aria-label="减少" disabled={count <= 2} onClick={remove}>
            <icons.Minus className="size-4" />
          </ui.IconButton>
          <span className="w-16 text-center text-tau-body text-ink-1">{count} 张卡片</span>
          <ui.IconButton aria-label="增加" disabled={count >= NAMES.length} onClick={add}>
            <icons.Plus className="size-4" />
          </ui.IconButton>
        </div>
        <label className="flex min-w-[200px] flex-1 items-center gap-3">
          <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">偏移</span>
          <input
            type="range"
            min={4}
            max={24}
            step={2}
            value={step}
            onChange={event => setStep(Number(event.target.value))}
            className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
          />
          <span className="w-12 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{step}px</span>
        </label>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Switch checked={reverseZ} onCheckedChange={setReverseZ} label="反转 z-index" size="sm" />
        <ui.Button variant="secondary" size="sm" icon={icons.ArrowDownToLine} onClick={rotate}>
          顶部卡片移到末尾
        </ui.Button>
      </div>
      <code className="w-fit min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
        z-index: {reverseZ ? "calc(sibling-count() - sibling-index())" : "auto"};
      </code>
    </div>
  );
};
